using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;

// --- Tool implementations -----------------------------------------------

/// <summary>Tools the research agent can invoke during its agentic loop.</summary>
static class ResearchTools
{
    // In-memory notebook shared across tool invocations.
    private static readonly List<string> _notes = [];

    [Description("Search the web for a query and return a list of result snippets. Use this to gather information about a topic.")]
    public static async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            using var http = new HttpClient();
            http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

            // Use DuckDuckGo instant-answer API (no key required).
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1";
            var json = await http.GetStringAsync(url);
            var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new StringBuilder();

            // Abstract (main answer)
            var abstractText = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                var source = root.GetProperty("AbstractSource").GetString();
                results.AppendLine($"[{source}] {abstractText}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                        results.AppendLine($"• {text.GetString()}");
                }
            }

            var output = results.ToString().Trim();
            return string.IsNullOrWhiteSpace(output)
                ? $"No detailed results found for \"{query}\". Try refining or rephrasing the query."
                : output;
        }
        catch (Exception ex)
        {
            return $"Search failed ({ex.GetType().Name}): {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record important findings you want to reference later in the summary.")]
    public static string SaveNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        Console.ResetColor();
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes so far.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i]}");
        return sb.ToString().Trim();
    }
}

// --- Main ----------------------------------------------------------------

var apiKey  = Environment.GetEnvironmentVariable("OPENAI_API_KEY")  ?? "";
var model   = Environment.GetEnvironmentVariable("OPENAI_MODEL")    ?? "gpt-4o-mini";
var baseUrl = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    Console.Error.WriteLine("Optionally set OPENAI_MODEL (default: gpt-4o-mini) and OPENAI_BASE_URL.");
    return 1;
}

// Build the chat client with tool support.
var clientOptions = new OpenAI.OpenAIClientOptions();
if (!string.IsNullOrWhiteSpace(baseUrl))
    clientOptions.Endpoint = new Uri(baseUrl);

var openAIClient = new OpenAI.OpenAIClient(new System.ClientModel.ApiKeyCredential(apiKey), clientOptions);

IChatClient chatClient = openAIClient
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// Prompt the user for a topic.
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided.");
    return 1;
}

Console.WriteLine($"\n🤖 Researching \"{topic}\"...\n");

// Set up the agent conversation.
var systemPrompt = """
    You are a research assistant. Your goal is to thoroughly research a topic
    provided by the user, then produce a well-organized summary.

    Follow this process:
    1. Use the SearchWeb tool multiple times with varied queries to gather
       broad and specific information about the topic.
    2. After each search, use the SaveNote tool to record the most important
       facts, statistics, or insights you find.
    3. Once you have gathered enough information (at least 3-4 searches),
       use GetNotes to review everything you have collected.
    4. Finally, produce a clear, structured summary with sections and key
       takeaways. Cite sources where possible.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(ResearchTools.SearchWeb),
        AIFunctionFactory.Create(ResearchTools.SaveNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ]
};

// Run the agentic loop — the model will call tools as needed.
var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("═══════════════════ Research Summary ═══════════════════");
Console.ResetColor();
Console.WriteLine(response.Text);
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("════════════════════════════════════════════════════════");
Console.ResetColor();

return 0;

