21.     clientOptions.Endpoint = new Uri(baseUrl);
22. 
23. var openAIClient = new OpenAI.OpenAIClient(new System.ClientModel.ApiKeyCredential(apiKey), clientOptions);
24. 
25. IChatClient chatClient = openAIClient
26.     .GetChatClient(model)
27.     .AsIChatClient()
28.     .AsBuilder()
29.     .UseFunctionInvocation()
30.     .Build();
31. 
32. // Prompt the user for a topic.
33. Console.Write("Enter a research topic: ");
34. var topic = Console.ReadLine()?.Trim();
35. if (string.IsNullOrWhiteSpace(topic))
36. {
37.     Console.Error.WriteLine("No topic provided.");
38.     return 1;
39. }
40. 
41. Console.WriteLine($"\n🤖 Researching \"{topic}\"...\n");
42. 
43. // Set up the agent conversation.
44. var systemPrompt = """
45.     You are a research assistant. Your goal is to thoroughly research a topic
46.     provided by the user, then produce a well-organized summary.
47. 
48.     Follow this process:
49.     1. Use the SearchWeb tool multiple times with varied queries to gather
50.        broad and specific information about the topic.
51.     2. After each search, use the SaveNote tool to record the most important
52.        facts, statistics, or insights you find.
53.     3. Once you have gathered enough information (at least 3-4 searches),
54.        use GetNotes to review everything you have collected.
55.     4. Finally, produce a clear, structured summary with sections and key
56.        takeaways. Cite sources where possible.
57.     """;
58. 
59. var messages = new List<ChatMessage>
60. {
61.     new(ChatRole.System, systemPrompt),
62.     new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
63. };
